const FORM_ENDPOINT='';const form=document.getElementById('contact-form');const succes=document.querySelector('.succes');const formError=document.querySelector('.form-error');const submitBtn=form?form.querySelector('.form__submit'):null;const pageOpenedAt=Date.now();function reachGoal(name){if(typeof window.trackGoal==='function')window.trackGoal(name);}
if(form){form.addEventListener('submit',function(e){e.preventDefault();const nameVal=(this.name.value||'').trim();const phoneVal=(this.phone.value||'').trim();const commentVal=(this.comment.value||'').trim();succes&&succes.classList.add('disp');formError&&formError.classList.add('disp');if(!nameVal){this.name.focus();return;}
if(!phoneVal){this.phone.focus();return;}
if(!FORM_ENDPOINT){formError&&formError.classList.remove('disp');return;}
if(submitBtn){submitBtn.disabled=true;}
const body=new URLSearchParams({name:nameVal,phone:phoneVal,comment:commentVal,website:this.website?this.website.value:'',elapsed:String(Date.now()-pageOpenedAt)});fetch(FORM_ENDPOINT,{method:'POST',body:body}).then(function(response){return response.json();}).then(function(data){if(!data||!data.ok){throw new Error((data&&data.error)||'Request failed');}
if(succes){succes.classList.remove('disp');}
reachGoal('form_submit');form.reset();}).catch(function(err){console.warn(err);if(formError){formError.classList.remove('disp');}}).finally(function(){if(submitBtn){submitBtn.disabled=false;}});});}